using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Windows;using System.Windows.Media;using System.Windows.Threading;using RingTimer;
class MotionPerformance {
 static void Pump(int ms){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 [STAThread]static int Main(string[] args){Native.SetProcessDPIAware();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};MenuWindow menu=null;Bubble bubble=null;var settings=new AppearanceSettings(null);try{
 string mode=args[2];bool enforce=args.Length>3&&args[3]=="enforce";Theme.Apply(true,null,null,null);var engine=new TimerEngine(new TimerState(),()=>DateTime.UtcNow);menu=new MenuWindow(new FeatureRegistry(new TimerFeature(engine,()=>{}),new StatsFeature(new StatsStore(null))),()=>{},()=>{},settings){Left=70,Top=30,AnimationsEnabled=false};menu.OpenFeature("timer");menu.Reveal();Pump(450);
 bubble=new Bubble();bubble.Show();double dpi=Native.ScaleFor(menu.Handle);var bounds=menu.PixelBounds;var b=bubble.PixelBounds;bubble.MovePixels(bounds.Right-(int)(Theme.LauncherDockInset*dpi)-b.Width,bounds.Bottom-(int)(Theme.LauncherDockInset*dpi)-b.Height);bubble.SetContext(new ContextUsage{Known=true,Used=60000,Capacity=100000});menu.Launcher=bubble;menu.AnchorBounds=()=>bubble.PixelBounds;menu.RestoreCardContour();menu.AnimationsEnabled=true;Pump(350);
 var card=menu.CardPresenter;var start=bubble.PixelBounds;var down=new Native.POINT{X=start.Left+20,Y=start.Top+20};bubble.PositionChanged=()=>MenuApplication.PlacePanel(bubble,menu,-1);if(mode=="tilt")card.Begin(new Point(180,250));else bubble.BeginDrag(down);
 var clock=Stopwatch.StartNew();var intervals=new List<double>();var frame=new DispatcherFrame();TimeSpan stamp=TimeSpan.MinValue;double last=-1;long frames=0,unique=0,duplicates=0;var previous=bubble.PixelBounds;var process=Process.GetCurrentProcess();TimeSpan cpu=process.TotalProcessorTime;
 EventHandler render=(s,e)=>{var rt=((RenderingEventArgs)e).RenderingTime;if(rt==stamp){duplicates++;return;}stamp=rt;double t=clock.Elapsed.TotalSeconds;bool updated=true;
 if(mode=="tilt")card.Move(new Point(180+160*Math.Sin(t*2.4),250+220*Math.Cos(t*1.8)));
 else {var current=bubble.PixelBounds;updated=current.Left!=previous.Left||current.Top!=previous.Top;previous=current;bubble.UpdateDrag(new Native.POINT{X=down.X+(int)(140*Math.Sin(t*2.7)),Y=down.Y+(int)(80*Math.Cos(t*2.1))});}
 if(t>=1){unique++;if(updated){if(last>=0)intervals.Add((t-last)*1000);last=t;frames++;}}if(t>=7)frame.Continue=false;};
 CompositionTarget.Rendering+=render;var limit=new DispatcherTimer{Interval=TimeSpan.FromSeconds(10)};limit.Tick+=(s,e)=>frame.Continue=false;limit.Start();try{Dispatcher.PushFrame(frame);}finally{CompositionTarget.Rendering-=render;limit.Stop();}
 intervals.Sort();process.Refresh();double seconds=clock.Elapsed.TotalSeconds,rate=frames/Math.Max(1,seconds-1);string report="label="+args[1]+" mode="+mode+" tier="+(RenderCapability.Tier>>16)+" dpi="+dpi+" updates_per_second="+rate.ToString("F1")+" unique_callbacks="+unique+" duplicate_callbacks="+duplicates+" median_ms="+(intervals.Count==0?0:intervals[intervals.Count/2]).ToString("F2")+" p95_ms="+(intervals.Count==0?0:intervals[(int)((intervals.Count-1)*.95)]).ToString("F2")+" cpu_one_core_percent="+((process.TotalProcessorTime-cpu).TotalSeconds/seconds*100).ToString("F1")+" private_mb="+(process.PrivateMemorySize64/1048576.0).ToString("F1")+" budget_90="+(rate>=90?"PASS":"BELOW_TARGET");Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],args[1]+"-"+mode+".txt"),report);Console.WriteLine(report);if(mode=="tilt")card.Release();else bubble.EndDrag();Pump(450);return enforce&&rate<90?2:0;
 }catch(Exception e){Console.WriteLine(e);return 1;}finally{if(menu!=null){menu.Disposing=true;menu.Close();}if(bubble!=null)bubble.Close();settings.Dispose();app.Shutdown();}}
}
